func TestExecutionAndAuthorization(t *testing.T){events:=0;server:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){if r.Header.Get("Authorization")!="Bearer fixture"{w.WriteHeader(401);w.Write([]byte(`{"error":{"code":"UNAUTHORIZED","message":"Denied"}}`));return};if r.URL.Path=="/api/runtime/outcomes"{events++;json.NewEncoder(w).Encode(map[string]any{"metrics":map[string]any{"success":events==1}});return};json.NewEncoder(w).Encode(map[string]any{"traceId":"trace","configuration":map[string]any{"model":"fixture"}})}));defer server.Close();client:=New(server.URL,"fixture","development");result,err:=client.Execute(context.Background(),"support",map[string]any{"userId":"user"},nil,"question","",func(context.Context,Resolved,string)(Completion,error){return Completion{Output:"answer"},nil},nil);if err!=nil||result.Output!="answer"||result.TelemetryError!=nil{t.Fatal(result,err)};failed,err:=client.Execute(context.Background(),"support",nil,nil,"question","",func(context.Context,Resolved,string)(Completion,error){return Completion{},errors.New("provider failed")},nil);if err!=nil||failed.ExecutionError==nil||events!=2{t.Fatal(failed,err,events)};_,err=New(server.URL,"bad","development").Resolve(context.Background(),"support",nil,nil);var apiErr *APIError;if !errors.As(err,&apiErr)||apiErr.Status!=401{t.Fatal(err)}}
